      SUBROUTINE MRR3CC     MULTIPLIES R AND RC3 AND STORES RESULT IN RC3CC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RC3.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TC3.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'U.CIN'      INCLUDE 'UC3.CIN'      INCLUDE 'US.CIN'CC---------------------------------------------------------------      IF (R3P) GO TO 50      DO 10 JK = 1, 36   10 RC3L(JK) = RL(JK)      IF (NORD2 .GE. 2) THEN        DO 20 JKM = 1, 105   20   TC3L(JKM) = TL(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   UC3L(JKLM) = UL(JKLM)      ENDIF      GO TO 100C   50 IF (NORD2 .EQ. 1) THEN        CALL CAB(RS,R,RC3)      ELSE IF (NORD2 .EQ. 2) THEN        CALL CAB2(RS,TS,R,T,RC3,TC3)      ELSE IF (NORD2 .GE. 3) THEN        CALL CAB3(RS,TS,US,R,T,U,RC3,TC3,UC3)      ENDIFC      DO 60 JK = 1, 36   60 RC3L(JK) = RSL(JK)      IF (NORD2 .GE. 2) THEN        DO 70 JKM = 1, 105   70   TC3L(JKM) = TSL(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 80 JKLM = 1, 280   80   UC3L(JKLM) = USL(JKLM)      ENDIFC  100 RETURN      END